```python
from playwright.sync_api import sync_playwright

START_URL = "https://ericko.dev/reprobot/"
SCREENSHOT_PATH = "/workspace/repro_f341c39d.png"


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(
            executable_path="/usr/bin/google-chrome",
            headless=True,
        )
        context = browser.new_context(viewport={"width": 1280, "height": 900})
        page = context.new_page()

        # Step 1: Navigate to Corner Diner page
        page.goto(START_URL, wait_until="networkidle")

        # Step 2: Click "Add to order" for Blueberry Pancakes ($9.25)
        page.locator('button[data-add="pancakes"]').click()

        # Step 3: Click Cart button in the top-right header
        page.locator('button[aria-label="Open cart"]').click()

        # Step 4 & 5: Click and type 'diner10' into the 'Enter code' input field
        promo_input = page.locator("#promo-input")
        promo_input.click()
        promo_input.fill("diner10")

        # Step 6: Click 'Apply' button next to the promo code input
        page.locator('#promo-form button[type="submit"]').click()

        # Step 7: Evaluate the report's check in the page
        result = page.evaluate(
            """() => {
                const errEl = document.querySelector('#promo-error');
                const totalEl = document.querySelector('#total');
                const subtotalEl = document.querySelector('#subtotal');
                const taxEl = document.querySelector('#tax');
                const errVisible = !!(errEl && errEl.offsetParent !== null && errEl.innerText.trim().length > 0);
                const errText = errEl ? errEl.innerText.trim() : '';
                const totalText = totalEl ? totalEl.innerText.trim() : '';
                const subtotalText = subtotalEl ? subtotalEl.innerText.trim() : '';
                const taxText = taxEl ? taxEl.innerText.trim() : '';
                return {
                    errVisible,
                    errText,
                    totalText,
                    subtotalText,
                    taxText,
                    bugPresent: errVisible && errText.includes('Sorry, that code is not valid.') && totalText === '$10.07'
                };
            }"""
        )

        page.screenshot(path=SCREENSHOT_PATH, full_page=True)

        if result["bugPresent"]:
            print("BUG_PRESENT")
        else:
            print("BUG_ABSENT")
        print(f"Observed: error={result['errText']!r}, subtotal={result['subtotalText']!r}, tax={result['taxText']!r}, total={result['totalText']!r}")

        browser.close()


if __name__ == "__main__":
    main()
```

